// Config: edit these values once. Every other node reads them via $('Config').first().json
// If n8n runs in Docker and Neo4j/Ollama run on the host, use host.docker.internal.
// If n8n runs directly on Windows (npm / desktop), use localhost.
return [{
  json: {
    neo4j_url: 'http://host.docker.internal:7474',
    neo4j_db: 'neo4j',
    ollama_url: 'http://host.docker.internal:11434',
    embed_model: 'nomic-embed-text',
    // Scryfall set code(s) to ingest. One set is ~250-300 cards. Space separated for several: 'fdn dsk'
    set_codes: 'fdn',
    // Paste the current TXT link from https://magic.wizards.com/en/rules
    cr_url: 'https://media.wizards.com/2026/downloads/MagicCompRules 20260619.txt',
  },
}];

// Splits the Comprehensive Rules TXT into one chunk per numbered rule (e.g. 702.19 incl. 702.19a-e).
// Rules longer than MAX characters are split on line boundaries into #1, #2, ...
const MAX = 3500;

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

const raw = String($input.first().json.data ?? '').replace(/^﻿/, '').replace(/\r/g, '');
const lines = raw.split('\n').map(l => l.trim());
const version = (raw.match(/effective as of ([^.\n]+)/i) ?? [])[1]?.trim() ?? 'unknown';

const start = lines.findIndex(l => /^100\.1\. /.test(l));
if (start < 0) throw new Error('Rule 100.1 not found - is cr_url pointing at the Comprehensive Rules TXT?');
let end = lines.findIndex((l, i) => i > start && l === 'Glossary');
if (end < 0) end = lines.length;

// Section titles ("702. Keyword Abilities") from the table of contents and the body
const sections = {};
for (const l of lines.slice(0, end)) {
  const m = l.match(/^(\d{3})\. (.+)$/);
  if (m) sections[m[1]] = m[2];
}

const rules = [];
let cur = null;
for (const l of lines.slice(start, end)) {
  if (!l) continue;
  if (/^\d\. [A-Z]/.test(l) || /^\d{3}\. /.test(l)) { cur = null; continue; } // chapter / section headers
  const m = l.match(/^(\d{3})\.(\d+)\. (.+)$/);
  if (m) {
    cur = { number: `${m[1]}.${m[2]}`, section: m[1], heading: m[3], lines: [l] };
    rules.push(cur);
    continue;
  }
  if (cur) cur.lines.push(l); // subrules like 702.19a and "Example:" lines
}

const out = [];
for (const r of rules) {
  // Keyword rules have a bare title ("Trample"); normal rules are full sentences ending with '.'
  const title = r.heading.endsWith('.') ? null : r.heading;
  const sectionTitle = sections[r.section] ?? null;
  const header = `Comprehensive Rules > ${r.section}. ${sectionTitle ?? ''} > ${r.number}${title ? ' ' + title : ''}`;

  const parts = [];
  let buf = [];
  let len = 0;
  for (const l of r.lines) {
    if (buf.length && len + l.length > MAX) { parts.push(buf); buf = []; len = 0; }
    buf.push(l);
    len += l.length + 1;
  }
  if (buf.length) parts.push(buf);

  parts.forEach((p, idx) => {
    const text = `${header}\n${p.join('\n')}`;
    out.push({
      json: {
        chunk_id: `rule:${r.number}${parts.length > 1 ? '#' + (idx + 1) : ''}`,
        source_type: 'rule',
        parent_id: r.number,
        number: r.number,
        section: r.section,
        section_title: sectionTitle,
        title,
        cr_version: version,
        text,
        hash: fnv1a(text),
        source: `Magic Comprehensive Rules (effective ${version}), rule ${r.number}`,
      },
    });
  });
}

return out;

// One row per rule (chunks split into #1/#2 share the same Rule node).
const STATEMENT = "UNWIND $rows AS row\nMERGE (s:Rule {number: row.section})\nSET s.title = row.section_title, s.level = 'section'\nMERGE (r:Rule {number: row.number})\nSET r.title = row.title, r.section = row.section, r.level = 'rule', r.cr_version = row.cr_version\nMERGE (r)-[:SUBRULE_OF]->(s)";
const BATCH = 200;

const byNumber = new Map();
for (const { json: c } of $input.all()) {
  if (!byNumber.has(c.number)) {
    byNumber.set(c.number, {
      number: c.number, section: c.section, section_title: c.section_title,
      title: c.title, cr_version: c.cr_version,
    });
  }
}
const rows = [...byNumber.values()];
const out = [];
for (let i = 0; i < rows.length; i += BATCH) {
  out.push({ json: { statements: [{ statement: STATEMENT, parameters: { rows: rows.slice(i, i + BATCH) } }] } });
}
return out;

// The Neo4j HTTP API returns 200 even when Cypher fails, so fail loudly here.
for (const item of $input.all()) {
  const errors = item.json.errors ?? [];
  if (errors.length) throw new Error('Neo4j error: ' + JSON.stringify(errors));
}
return [{ json: { ok: true, batches: $input.all().length } }];

// Duplicate check: ask Neo4j which chunks already exist and with which content hash.
const ids = $input.all().map(i => i.json.chunk_id);
return [{
  json: {
    statements: [{
      statement: 'MATCH (ch:Chunk) WHERE ch.id IN $ids RETURN ch.id AS id, ch.hash AS hash',
      parameters: { ids },
    }],
  },
}];

// Keep only new chunks or chunks whose text changed. Unchanged chunks are not re-embedded.
const res = $input.first().json;
if (res.errors?.length) throw new Error('Neo4j error: ' + JSON.stringify(res.errors));
const existing = new Map((res.results?.[0]?.data ?? []).map(d => [d.row[0], d.row[1]]));

const chunks = $("Back to rule chunks").all().map(i => i.json);
const changed = chunks.filter(c => existing.get(c.chunk_id) !== c.hash);
const skipped = chunks.length - changed.length;
console.log(`Chunks: ${chunks.length}, unchanged (skipped): ${skipped}, to embed: ${changed.length}`);
return changed.map(c => ({ json: c }));

// Each Ollama response holds 32 embeddings; flatten them back onto the chunks in order
const chunks = $('Filter changed chunks').all().map(i => i.json);
const embeddings = $input.all().flatMap(i => i.json.embeddings ?? []);
if (embeddings.length !== chunks.length) {
  throw new Error(`Got ${embeddings.length} embeddings for ${chunks.length} chunks`);
}
return chunks.map((c, idx) => ({ json: { ...c, embedding: embeddings[idx] } }));

// Upserts chunks with their embedding. Label and parent link depend on the chunk type.
const BASE = "UNWIND $rows AS row\nMERGE (ch:Chunk {id: row.chunk_id})\nSET ch:__LABEL__, ch.text = row.text, ch.source = row.source,\n    ch.source_type = row.source_type, ch.hash = row.hash\nWITH ch, row\nCALL db.create.setNodeVectorProperty(ch, 'embedding', row.embedding)\nWITH ch, row\n__LINK__";
const LABEL = { card: 'CardChunk', ruling: 'RulingChunk', rule: 'RuleChunk' };
const LINK = {
  card: 'MATCH (p:Card {oracle_id: row.parent_id}) MERGE (p)-[:HAS_CHUNK]->(ch)',
  ruling: 'MATCH (p:Card {oracle_id: row.parent_id}) MERGE (p)-[:HAS_RULINGS]->(ch)',
  rule: 'MATCH (p:Rule {number: row.parent_id}) MERGE (p)-[:HAS_CHUNK]->(ch)',
};
const BATCH = 50;

const byType = {};
for (const { json: c } of $input.all()) {
  (byType[c.source_type] ??= []).push({
    chunk_id: c.chunk_id, parent_id: c.parent_id, source_type: c.source_type,
    text: c.text, hash: c.hash, source: c.source, embedding: c.embedding,
  });
}

const out = [];
for (const [type, rows] of Object.entries(byType)) {
  const statement = BASE.replace('__LABEL__', LABEL[type]).replace('__LINK__', LINK[type]);
  for (let i = 0; i < rows.length; i += BATCH) {
    out.push({ json: { statements: [{ statement, parameters: { rows: rows.slice(i, i + BATCH) } }] } });
  }
}
return out;

// Links Keyword nodes (from Scryfall) to the Comprehensive Rule that defines them (701.x / 702.x).
for (const item of $input.all()) {
  if (item.json.errors?.length) throw new Error('Neo4j error: ' + JSON.stringify(item.json.errors));
}
return [{ json: { statements: [{ statement: "MATCH (k:Keyword)\nMATCH (r:Rule {level: 'rule'})\nWHERE r.section IN ['701', '702'] AND toLower(r.title) = toLower(k.name)\nMERGE (k)-[:DEFINED_BY]->(r)\nRETURN count(*) AS linked", parameters: {} }] } }];

// The Neo4j HTTP API returns 200 even when Cypher fails, so fail loudly here.
for (const item of $input.all()) {
  const errors = item.json.errors ?? [];
  if (errors.length) throw new Error('Neo4j error: ' + JSON.stringify(errors));
}
return [{ json: { ok: true, batches: $input.all().length } }];

// 32 texts per request instead of one request per chunk
const BATCH = 32;
const chunks = $input.all().map(i => i.json);
const out = [];
for (let i = 0; i < chunks.length; i += BATCH) {
  out.push({ json: { inputs: chunks.slice(i, i + BATCH).map(c => 'search_document: ' + c.text) } });
}
return out;
